changeSet.sql:
CREATE SEQUENCE IF NOT EXISTS public.payment_use_case_catalog_id_seq
    INCREMENT BY 1 NO MINVALUE NO MAXVALUE START WITH 1 CACHE 1;
CREATE TABLE public.payment_use_case_catalog (
    id bigint DEFAULT nextval('public.payment_use_case_catalog_id_seq'::regclass) NOT NULL,
    tenant_id character varying(255),
    code character varying(64) NOT NULL,
    label character varying(255) NOT NULL,
    hint character varying(255),
    sort_order integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT payment_use_case_catalog_pkey PRIMARY KEY (id),
    CONSTRAINT fk_payment_use_case_catalog__tenant_id FOREIGN KEY (tenant_id) REFERENCES public.tenant_organization(tenant_id) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE UNIQUE INDEX ux_payment_use_case_catalog__global_code ON public.payment_use_case_catalog (code) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX ux_payment_use_case_catalog__tenant_code ON public.payment_use_case_catalog (tenant_id, code) WHERE tenant_id IS NOT NULL;
CREATE INDEX idx_payment_use_case_catalog_tenant_active ON public.payment_use_case_catalog (tenant_id, is_active, sort_order);
COMMENT ON TABLE public.payment_use_case_catalog IS 'Assignable payment_provider_config.payment_use_case. Null tenant_id is the shared catalog. A null use case on the config row serves every product.';
CREATE TRIGGER trg_payment_use_case_catalog_updated_at
    BEFORE UPDATE ON public.payment_use_case_catalog
    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
